// 1. Get raw text safely
const item = $input.first();
const rawText = (item.json && item.json.text) ? String(item.json.text) : "";

// --- HELPER FUNCTIONS ---

function safeJSONParse(str) {
  try {
    return JSON.parse(str);
  } catch (e) {
    return null;
  }
}

function cleanAndParse(str) {
  if (!str) return null;
  let cleaned = str;
  cleaned = cleaned.replace(/```(?:json|xml|text)?/gi, "").replace(/```/g, "");
  cleaned = cleaned.replace(/([^\\:]|^)\/\/.*/g, '$1');
  cleaned = cleaned.replace(/,(\s*[}\]])/g, '$1');
  return safeJSONParse(cleaned);
}

// NEW: Extract HTML directly from the raw text using DOCTYPE/html markers
// This is 100% reliable regardless of JSON escaping issues
function extractHtmlDirect(text) {
  const startMarker = '<!DOCTYPE html>';
  const endMarker = '</html>';

  let htmlStart = text.indexOf(startMarker);
  if (htmlStart === -1) {
    // Try case-insensitive
    htmlStart = text.toLowerCase().indexOf(startMarker.toLowerCase());
  }
  if (htmlStart === -1) return "";

  let htmlEnd = text.lastIndexOf(endMarker);
  if (htmlEnd === -1) {
    htmlEnd = text.toLowerCase().lastIndexOf(endMarker.toLowerCase());
  }
  if (htmlEnd === -1) return "";

  let html = text.substring(htmlStart, htmlEnd + endMarker.length);

  // Unescape JSON string escapes (since this was inside a JSON string)
  html = html
    .replace(/\\n/g, '\n')
    .replace(/\\t/g, '\t')
    .replace(/\\r/g, '\r')
    .replace(/\\"/g, '"')
    .replace(/\\\\/g, '\\');

  return html;
}

// Simple field extractors for non-HTML fields
function extractString(text, key) {
  const regex = new RegExp(`"${key}"\\s*:\\s*"((?:[^"\\\\]|\\\\.)*)"`, 's');
  const match = text.match(regex);
  if (match && match[1]) {
    try { return JSON.parse(`"${match[1]}"`); } catch (e) { return match[1]; }
  }
  return "";
}

function extractBoolean(text, key) {
  const regex = new RegExp(`"${key}"\\s*:\\s*(true|false)`, 'i');
  const match = text.match(regex);
  return match ? match[1].toLowerCase() === 'true' : false;
}

// --- MAIN LOGIC ---

let replyMessage = "";
let isModification = false;
let updatedCvHtml = "";

// ATTEMPT 1: Full JSON parse (fastest, cleanest)
const firstBrace = rawText.indexOf('{');
const lastBrace = rawText.lastIndexOf('}');

if (firstBrace !== -1 && lastBrace !== -1) {
  const jsonSubstring = rawText.substring(firstBrace, lastBrace + 1);
  let parsed = safeJSONParse(jsonSubstring) || cleanAndParse(jsonSubstring);

  if (parsed) {
    replyMessage = parsed.replyMessage || "";
    isModification = parsed.isModification === true;
    updatedCvHtml = parsed.updatedCvHtml || "";
  }
}

// ATTEMPT 2: If JSON parse failed OR HTML is empty, extract directly
if (!updatedCvHtml) {
  updatedCvHtml = extractHtmlDirect(rawText);
}

// Extract other fields if JSON parse failed entirely
if (!replyMessage) {
  replyMessage = extractString(rawText, "replyMessage");
  isModification = extractBoolean(rawText, "isModification");
}

// If we found HTML, that means it IS a modification
if (updatedCvHtml && !isModification) {
  isModification = true;
}

// Final output
return {
  json: {
    isModification: isModification,
    replyMessage: replyMessage || "I encountered an error processing the CV. Please try again.",
    updatedCvHtml: updatedCvHtml
  }
};

// Get the output from whichever LLM node ran
const aiOutput = $input.first().json.updatedCvHtml;

// Get the original input data from the start of the workflow
// IMPORTANT: Replace 'Edit Fields' with the actual name of your Set node
const initialData = $input.first().json.text;

// Get the base64 string, which might be empty
const base64String = $input.first().json.data|| '';

// 1. Clean up potential markdown code fences from the AI output
let cleanedHtml = aiOutput.replace(/^```html\s*/, '').replace(/```$/, '').trim();

// 2. Replace the placeholder with the actual base64 data
// If base64String is empty, it will replace the placeholder with nothing (effectively removing the image src if the AI messes up)
// If the placeholder isn't found (the "no image" path), this does nothing.
let finalHtml = cleanedHtml.replace('%%PROFILE_PICTURE_BASE64%%', base64String);

// Return the final, complete HTML string
return {
  html: finalHtml
};

// Input: items array from your node
// Output: one item with all keys mapped

return [
  {
    json: items.reduce((acc, item) => {
      const { key, value, description, group_name } = item.json;
      // Make key the master
      acc[key] = {
        value,
        description,
        group: group_name
      };
      return acc;
    }, {})
  }
];

