// Get the output from whichever LLM node ran
const aiOutput = $input.first().json.text;

// Get the original input data from the start of the workflow
// IMPORTANT: Replace 'Edit Fields' with the actual name of your Set node

// Get the base64 string, which might be empty
const base64String = $input.first().json.data|| '';

// 1. Clean up potential markdown code fences from the AI output
let cleanedHtml = aiOutput.replace(/^```html\s*/, '').replace(/```$/, '').trim();

// 2. Replace the placeholder with the actual base64 data
// If base64String is empty, it will replace the placeholder with nothing (effectively removing the image src if the AI messes up)
// If the placeholder isn't found (the "no image" path), this does nothing.
let finalHtml = cleanedHtml.replace('%%PROFILE_PICTURE_BASE64%%', base64String);

// Return the final, complete HTML string
return {
  html: finalHtml
};

// Extract job and candidates from webhook body
const body = $input.first().json.body || $input.first().json;

const job = body.job;
const candidates = body.candidates || [];

if (!job || !candidates.length) {
  return [{ json: { error: 'Missing job or candidates data', rankings: [] } }];
}

// === JOB SUMMARY ===
const job_summary = {
  id: job.id,
  title: job.title,
  description: (job.description || '').replace(/<[^>]*>/g, '').slice(0, 800),
  skills_required: (job.skills_required || []),
  job_type: job.job_type || 'N/A',
  location: job.location || 'N/A',
  country: job.country || 'N/A',
  salary_range: job.salary_range || 'N/A',
};

// === CANDIDATES LIST ===
const candidates_list = candidates.map((c, i) => ({
  index: i + 1,
  id: c.id,
  name: c.name || 'Unknown',
  headline: c.headline || '',
  skills: (c.skills || []),
  skills_text: (c.skills || []).join(', '),
  years_experience: c.years_experience || 0,
  location: c.location || '',
  nationality: c.nationality || '',
  education: (c.education || []),
  education_text: (c.education || []).join(' | '),
  summary: (c.summary || '').slice(0, 300),
  cv_url: c.cv_url || null,
}));

// === ID MAP (for post-processing safety) ===
const id_map = {};
candidates_list.forEach(c => {
  id_map[`candidate_${c.index}`] = c.id;
  id_map[c.name.toLowerCase()] = c.id;
  id_map[c.id] = c.id;
});

// === PROMPT — IDs are prominent ===
const jobText = `الوظيفة: ${job.title}
الوصف: ${job_summary.description}
المهارات المطلوبة: ${job_summary.skills_required.join(', ') || 'غير محدد'}
النوع: ${job_summary.job_type}
الموقع: ${job_summary.location}
الراتب: ${job_summary.salary_range}`;

const candidatesText = candidates_list.map(c => 
  `[مرشح ${c.index}] candidate_id: "${c.id}" | الاسم: ${c.name} | المهارات: ${c.skills_text} | الخبرة: ${c.years_experience} سنة | التعليم: ${c.education_text} | الملخص: ${c.summary}`
).join('\n');

const prompt = `أنت خبير توظيف ذكي في سوق العمل الإماراتي والعربي.

حلّل الوظيفة التالية وقيّم المرشحين حسب مناسبتهم.

قواعد مهمة:
1. قيّم التطابق الدلالي للمهارات (مثلاً React تتعلق بـ Frontend)
2. اعتبر المهارات القابلة للنقل والخبرة في المجال
3. طابق مستوى التعليم مع متطلبات الوظيفة
4. أعطِ وزناً أعلى للتطابق الدقيق في المهارات
5. أجب بـ JSON فقط بدون markdown
6. ⚠️ مهم جداً: استخدم candidate_id بالضبط كما هو مكتوب (UUID) — لا تستخدم أسماء أو أرقام بديلة

=== الوظيفة ===
${jobText}

=== المرشحون ===
${candidatesText}

=== التنسيق المطلوب ===
أرجع JSON بهذا الشكل بالضبط:
{
  "rankings": [
    {
      "candidate_id": "انسخ الـ UUID بالضبط من بيانات المرشح أعلاه",
      "name": "الاسم",
      "score": 0-100,
      "reasoning": "شرح بالعربي لماذا هذا المرشح مناسب أو غير مناسب (2-3 جمل)",
      "strengths": ["مهارة1", "مهارة2"],
      "gaps": ["مهارة_ناقصة1"],
      "recommendation": "مناسب جداً" | "مناسب" | "مناسب جزئياً" | "غير مناسب"
    }
  ]
}

رتّب من الأعلى للأقل. كن عادلاً وتحليلياً.`;

// === OUTPUT ===
return [{ json: {
  prompt,
  job_summary,
  candidates_list,
  candidates_text: candidatesText,
  job_text: jobText,
  id_map,
  metadata: {
    job_id: job.id,
    employer_id: body.employer_id,
    candidate_count: candidates.length,
    timestamp: new Date().toISOString(),
  }
} }];

// Parse AI Agent response and fix candidate IDs
const rawText = $input.first().json.output || $input.first().json.text || '';

// Get id_map from the Build AI Prompt node
const buildNode = $('Build AI Prompt').first().json;
const idMap = buildNode.id_map || {};
const candidatesList = buildNode.candidates_list || [];

// Parse JSON from AI response
let result;
try {
  let cleaned = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  result = JSON.parse(cleaned);
} catch (e) {
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try { result = JSON.parse(jsonMatch[0]); } 
    catch (e2) { result = { rankings: [], error: 'Parse failed' }; }
  } else {
    result = { rankings: [], error: 'No JSON in response' };
  }
}

// Fix candidate IDs — map back to real UUIDs
if (result.rankings && Array.isArray(result.rankings)) {
  result.rankings = result.rankings.map(r => {
    let fixedId = r.candidate_id;

    // If AI returned a real UUID, keep it
    if (idMap[fixedId]) {
      fixedId = idMap[fixedId];
    }
    // If AI returned "candidate_1", "candidate_2", map to real UUID
    else if (idMap[fixedId.toLowerCase()]) {
      fixedId = idMap[fixedId.toLowerCase()];
    }
    // If AI returned the name, map to real UUID
    else if (r.name && idMap[r.name.toLowerCase()]) {
      fixedId = idMap[r.name.toLowerCase()];
    }
    // Last resort: match by index
    else {
      const indexMatch = fixedId.match(/(\d+)/);
      if (indexMatch) {
        const idx = parseInt(indexMatch[1]);
        const candidate = candidatesList.find(c => c.index === idx);
        if (candidate) fixedId = candidate.id;
      }
    }

    return { ...r, candidate_id: fixedId };
  });

  result.rankings.sort((a, b) => (b.score || 0) - (a.score || 0));
}

return [{ json: result }];

// 1. Get raw text safely
const item = $input.first();
// Ensure we have a string to work with
const rawText = (item.json && item.json.text) ? String(item.json.text) : "";

// --- HELPER FUNCTIONS ---

// Helper: Attempt to parse a clean string
function safeJSONParse(str) {
  try {
    return JSON.parse(str);
  } catch (e) {
    return null;
  }
}

// Helper: Sanitize common AI JSON errors (trailing commas, comments)
function cleanAndParse(str) {
  if (!str) return null;
  let cleaned = str;
  // Remove Markdown code blocks
  cleaned = cleaned.replace(/```(?:json|xml|text)?/gi, "").replace(/```/g, "");
  // Remove comments //...
  cleaned = cleaned.replace(/([^\\:]|^)\/\/.*/g, '$1');
  // Fix trailing commas (e.g., "key": "value", } -> "key": "value" })
  cleaned = cleaned.replace(/,(\s*[}\]])/g, '$1');

  return safeJSONParse(cleaned);
}

// Helper: Regex Fallback (The "Nuclear Option")
// If JSON parsing fails completely, this manually extracts the specific fields we need.
function manualExtract(text, key, type) {
  // Pattern looks for: "key": "captured_content"
  // It handles escaped quotes (\") inside the content correctly.
  const regex = new RegExp(`"${key}"\\s*:\\s*"((?:[^"\\\\]|\\\\.)*)"`);

  // Special handling for Booleans
  if (type === 'boolean') {
    const boolRegex = new RegExp(`"${key}"\\s*:\\s*(true|false)`, 'i');
    const match = text.match(boolRegex);
    return match ? match[1].toLowerCase() === 'true' : false;
  }

  const match = text.match(regex);
  if (match && match[1]) {
    // We found the content! Now we parse just this string to handle escapes (like \n) correctly
    try {
      return JSON.parse(`"${match[1]}"`); 
    } catch (e) {
      // If even that fails, return raw string
      return match[1]; 
    }
  }
  return "";
}

// --- MAIN LOGIC ---

let parsedData = null;

// 1. Try to find the JSON block ({ ... })
const firstBrace = rawText.indexOf('{');
const lastBrace = rawText.lastIndexOf('}');

if (firstBrace !== -1 && lastBrace !== -1) {
  const jsonSubstring = rawText.substring(firstBrace, lastBrace + 1);

  // ATTEMPT 1: Parse the extracted block directly
  parsedData = safeJSONParse(jsonSubstring);

  // ATTEMPT 2: Clean syntax errors and parse
  if (!parsedData) {
    parsedData = cleanAndParse(jsonSubstring);
  }
}

// ATTEMPT 3: Manual Regex Extraction (Fallback if all parsing failed)
if (!parsedData) {
  // If the structure is broken, we just grab the values we need directly from the raw text
  parsedData = {
    replyMessage: manualExtract(rawText, "replyMessage", "string"),
    isModification: manualExtract(rawText, "isModification", "boolean"),
    updatedCvHtml: manualExtract(rawText, "updatedCvHtml", "string")
  };
}

// 4. Final Validation
// If even regex failed to find "replyMessage", we fall back to a default error.
const finalData = {
  isModification: parsedData.isModification === true,
  replyMessage: parsedData.replyMessage || "I encountered an error processing the CV. Please try again.",
  updatedCvHtml: parsedData.updatedCvHtml || ""
};

// 5. Return
return {
  json: {
    isModification: finalData.isModification,
    replyMessage: finalData.replyMessage,
    updatedCvHtml: finalData.updatedCvHtml 
  }
};

